FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 018: feature options: split by a sheet, move face up to, curves, surfaces, mate connectors, sheet metal holes and unfolds. Generated by tools/fixtures/gen-batch-018.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function pointAtFraction(context is Context, part is Query, fx is number, fy is number, fz is number) returns Vector
{
    const b = evBox3d(context, { "topology" : part, "tight" : true });
    return vector(b.minCorner[0] + fx * (b.maxCorner[0] - b.minCorner[0]),
                  b.minCorner[1] + fy * (b.maxCorner[1] - b.minCorner[1]),
                  b.minCorner[2] + fz * (b.maxCorner[2] - b.minCorner[2]));
}

function atFraction(context is Context, part is Query, entityType is EntityType, fx is number, fy is number, fz is number) returns Query
{
    return qContainsPoint(qOwnedByBody(part, entityType), pointAtFraction(context, part, fx, fy, fz));
}

function bodyCounts(context is Context) returns map
{
    const all = qEverything(EntityType.BODY);
    return { "solids" : evaluateQueryCount(context, qBodyType(all, BodyType.SOLID)),
             "active" : evaluateQueryCount(context, qActiveSheetMetalFilter(all, ActiveSheetMetal.YES)) };
}

// A mate connector's coordinate system, rounded so it compares as text.
function connectorFrame(context is Context, connector is Query) returns map
{
    const cs = evMateConnector(context, { "mateConnector" : connector });
    return { "origin" : roundVector(cs.origin / millimeter), "x" : roundVector(cs.xAxis), "z" : roundVector(cs.zAxis) };
}

function roundVector(v is Vector) returns Vector
{
    return vector(round(v[0] * 1e6) / 1e6, round(v[1] * 1e6) / 1e6, round(v[2] * 1e6) / 1e6);
}

// split: a block split by a curved sheet
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const cutSketch = newSketchOnPlane(context, id + "cutSketch", { "sketchPlane" : plane(vector(0, 0, -5) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(cutSketch, "arc1", { "start" : vector(10, -5) * millimeter, "mid" : vector(18, 10) * millimeter, "end" : vector(10, 25) * millimeter });
    skSolve(cutSketch);
    extrude(context, id + "cut", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "cutSketch", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    splitPart(context, id + "split1", { "targets" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "tool" : qBodyType(qCreatedBy(id + "cut", EntityType.BODY), BodyType.SHEET) });
}

